// Secure remote exec on the .215 dev box, mirroring the platform ssh approach.
// Decrypts server.rootPasswordEnc and feeds it straight into ssh2 — never prints it.
// Usage: node sshx.cjs '<remote bash command>'
// Asserts the host is 51.79.226.215 before running anything.
require("dotenv").config({ path: "/opt/nxeon/.env" });
const { Client } = require("ssh2");
const { PrismaClient } = require("@prisma/client");
const { scryptSync, createDecipheriv } = require("node:crypto");

const SERVER_ID = "cmsecmdps0001hlp27ai6mr7c";
const EXPECT_IP = "51.79.226.215";

function decryptSecret(enc) {
  if (!enc) return null;
  try {
    const key = scryptSync(process.env.AUTH_SECRET, "nxeon-byok", 32);
    const [ivB64, tagB64, dataB64] = enc.split(":");
    if (!ivB64 || !tagB64 || !dataB64) return null;
    const d = createDecipheriv("aes-256-gcm", key, Buffer.from(ivB64, "base64"));
    d.setAuthTag(Buffer.from(tagB64, "base64"));
    return Buffer.concat([d.update(Buffer.from(dataB64, "base64")), d.final()]).toString("utf8");
  } catch { return null; }
}

(async () => {
  const cmd = process.argv[2];
  if (!cmd) { console.error("no command"); process.exit(2); }
  const prisma = new PrismaClient();
  const s = await prisma.server.findUnique({ where: { id: SERVER_ID } });
  await prisma.$disconnect();
  if (!s) { console.error("server row not found"); process.exit(3); }
  const host = s.ipAddress || EXPECT_IP;
  if (host !== EXPECT_IP) { console.error("REFUSE: host " + host + " != " + EXPECT_IP); process.exit(4); }
  const password = decryptSecret(s.rootPasswordEnc) || s.rootPassword;
  if (!password) { console.error("no root password"); process.exit(5); }
  const port = s.sshPort && s.ipAddress == null ? s.sshPort : 22;

  const conn = new Client();
  conn.on("ready", () => {
    // Assert identity remotely too, then run the command.
    const guarded = `test "$(hostname -I | tr ' ' '\\n' | grep -x ${EXPECT_IP})" = "${EXPECT_IP}" || { echo "REMOTE-IP-ASSERT-FAILED" >&2; exit 9; }; ` + cmd;
    conn.exec(guarded, (err, stream) => {
      if (err) { console.error(err.message); process.exit(6); }
      let code = 0;
      stream.on("close", (c) => { conn.end(); process.exit(c || 0); });
      stream.on("data", (d) => process.stdout.write(d));
      stream.stderr.on("data", (d) => process.stderr.write(d));
    });
  });
  conn.on("error", (e) => { console.error("SSH ERROR: " + e.message); process.exit(7); });
  conn.connect({ host, port, username: "root", password, readyTimeout: 15000 });
})();

