11	
12	export type StudioStripeConfig = { secretKey?: string; connectedAt?: string; accountLabel?: string };
13	
14	export function platformStripe(): Stripe | null {
15	  const key = process.env.STRIPE_SECRET_KEY;
16	  return key ? new Stripe(key) : null;
17	}
18	
19	export function studioStripeConfig(tenant: Pick<Tenant, "policies">): StudioStripeConfig {
20	  return (((tenant.policies ?? {}) as Record<string, unknown>).stripe ?? {}) as StudioStripeConfig;
21	}
22	
23	export function studioStripe(tenant: Pick<Tenant, "policies">): Stripe | null {
24	  const key = studioStripeConfig(tenant).secretKey;
25	  return key ? new Stripe(key) : null;
26	}
27	
28	export function studioStripeEnabled(tenant: Pick<Tenant, "policies">): boolean {
29	  return !!studioStripeConfig(tenant).secretKey;
30	}
31	
32	// Validate a pasted key by hitting the API; returns the account label.
33	export async function verifyStripeKey(secretKey: string): Promise<{ ok: true; label: string } | { ok: false }> {
34	  try {
35	    const s = new Stripe(secretKey);
36	    const bal = await s.balance.retrieve();
37	    return { ok: true, label: `account in ${(bal.available[0]?.currency ?? "usd").toUpperCase()}` };
38	  } catch {
39	    return { ok: false };
40	  }
41	}
