43	// Zero-decimal currencies charge whole units in Stripe.
44	const ZERO_DECIMAL = new Set(["JPY", "KRW", "VND"]);
45	export function toStripeAmount(amount: number, currency: string): number {
46	  return Math.round(ZERO_DECIMAL.has(currency.toUpperCase()) ? amount : amount * 100);
47	}
