10	// Stripe Checkout success landing for a gift-card purchase. Mirrors the package
11	// confirm flow: verify the session server-side (no webhook needed for
12	// studio-level payments), then mint the card exactly once. Idempotency is
13	// enforced by the unique GiftCard.stripeSessionId — a refresh/retry of this URL
14	// finds the existing card instead of creating a duplicate.
15	export async function GET(req: Request) {
16	  const url = new URL(req.url);
17	  const slug = url.searchParams.get("slug") ?? "";
18	  const sid = url.searchParams.get("sid") ?? "";
