20	
21	  const tenant = await tenantBySlugOrDomain(slug);
22	  const stripe = tenant ? studioStripe(tenant) : null;
23	  if (!tenant || !stripe || !sid) return NextResponse.redirect(externalUrl(req, `${back}?err=stripe`), 303);
24	
25	  try {
26	    const session = await stripe.checkout.sessions.retrieve(sid);
27	    if (session.payment_status !== "paid" || session.metadata?.tenantId !== tenant.id || session.metadata?.kind !== "giftcard") {
28	      return NextResponse.redirect(externalUrl(req, `${back}?err=stripe`), 303);
29	    }
30	
31	    let card = await db.giftCard.findUnique({ where: { stripeSessionId: sid } });
32	    if (!card) {
33	      const amount = Math.round((Number(session.metadata.amount ?? 0) || 0) * 100) / 100;
34	      const recipientEmail = (session.metadata.recipientEmail || "").trim() || null;
35	      const purchaserEmail = (session.metadata.purchaserEmail || session.customer_details?.email || "").trim() || null;
36	      const message = (session.metadata.message || "").trim() || null;
37	      const code = await allocateUniqueCode(db, tenant.id);
38	      const expiresAt = new Date(Date.now() + GIFT_CARD_VALIDITY_DAYS * 86400_000);
39	      card = await db.$transaction(async (tx) => {
40	        const created = await tx.giftCard.create({
41	          data: {
42	            tenantId: tenant.id,
43	            code,
44	            initialAmount: amount.toFixed(2),
45	            balance: amount.toFixed(2),
46	            currency: tenant.currency,
47	            purchaserEmail,
48	            recipientEmail,
49	            message,
