67	        const { subject, body } = purchaseEmailBody({
68	          studio: tenant.name,
69	          amount: fmt.format(Number(card.initialAmount)),
70	          code: card.code,
71	          message: card.message,
72	          viewUrl,
73	        });
74	        await sendEmail({ tenantId: tenant.id, to, subject, body }).catch(() => {});
75	      }
76	    }
