import type { Tenant } from "@prisma/client";

// ── PayPal framework (per-tenant, alternative to Stripe) ───────────────
// Each studio pastes its OWN PayPal REST app credentials (Settings → Money,
// stored in policies.paypal) — the studio charging ITS clients for packages
// and gift cards through PayPal Orders v2. Fully dormant until a studio saves
// a clientId + secret and flips `enabled` on; if unconfigured it stays dark and
// no PayPal button ever renders. No credentials are ever invented.
//
// Mirrors lib/stripe.ts (studioStripe / studioStripeConfig / studioStripeEnabled).

export type PayPalMode = "sandbox" | "live";

export type StudioPayPalConfig = {
  clientId?: string;
  secret?: string;
  mode?: PayPalMode;
  enabled?: boolean;
  /** Optional: the studio's registered webhook id, used to verify webhook signatures. */
  webhookId?: string;
  connectedAt?: string;
  accountLabel?: string;
};

export function studioPayPalConfig(tenant: Pick<Tenant, "policies">): StudioPayPalConfig {
  return (((tenant.policies ?? {}) as Record<string, unknown>).paypal ?? {}) as StudioPayPalConfig;
}

/** True only when a studio has saved creds AND explicitly enabled PayPal. */
export function studioPayPalEnabled(tenant: Pick<Tenant, "policies">): boolean {
  const c = studioPayPalConfig(tenant);
  return !!(c.enabled && c.clientId && c.secret);
}

/** The public client-id + mode the browser SDK needs (never the secret). */
export function studioPayPalPublic(
  tenant: Pick<Tenant, "policies">
): { clientId: string; mode: PayPalMode } | null {
  const c = studioPayPalConfig(tenant);
  if (!studioPayPalEnabled(tenant)) return null;
  return { clientId: c.clientId!, mode: c.mode === "live" ? "live" : "sandbox" };
}

export function paypalApiBase(mode: PayPalMode | undefined): string {
  return mode === "live" ? "https://api-m.paypal.com" : "https://api-m.sandbox.paypal.com";
}

// PayPal wants zero-decimal currencies as whole-number strings and everything
// else with exactly two decimals.
const ZERO_DECIMAL = new Set(["JPY", "KRW", "VND", "HUF", "TWD"]);
export function toPayPalAmount(amount: number, currency: string): string {
  return ZERO_DECIMAL.has(currency.toUpperCase())
    ? String(Math.round(amount))
    : amount.toFixed(2);
}

type Creds = Pick<StudioPayPalConfig, "clientId" | "secret" | "mode">;

/** OAuth2 client-credentials access token for a studio's PayPal app. */
async function accessToken(cfg: Creds): Promise<string> {
  if (!cfg.clientId || !cfg.secret) throw new Error("PayPal is not configured");
  const base = paypalApiBase(cfg.mode);
  const basic = Buffer.from(`${cfg.clientId}:${cfg.secret}`).toString("base64");
  const res = await fetch(`${base}/v1/oauth2/token`, {
    method: "POST",
    headers: {
      Authorization: `Basic ${basic}`,
      "Content-Type": "application/x-www-form-urlencoded",
    },
    body: "grant_type=client_credentials",
    cache: "no-store",
  });
  if (!res.ok) throw new Error(`PayPal auth failed (${res.status})`);
  const json = (await res.json()) as { access_token?: string };
  if (!json.access_token) throw new Error("PayPal auth: no token");
  return json.access_token;
}

export type PayPalOrderResult = { id: string; status: string };

/** Create an Orders-v2 order for a single purchase unit; server-computed amount. */
export async function createPayPalOrder(
  cfg: Creds,
  args: {
    currency: string;
    amount: number;
    description: string;
    referenceId: string; // "package" | "giftcard"
    customId?: string; // our intent id, echoed back on webhooks
  }
): Promise<PayPalOrderResult> {
  const base = paypalApiBase(cfg.mode);
  const token = await accessToken(cfg);
  const res = await fetch(`${base}/v2/checkout/orders`, {
    method: "POST",
    headers: { Authorization: `Bearer ${token}`, "Content-Type": "application/json" },
    cache: "no-store",
    body: JSON.stringify({
      intent: "CAPTURE",
      purchase_units: [
        {
          reference_id: args.referenceId,
          custom_id: args.customId,
          description: args.description.slice(0, 127),
          amount: {
            currency_code: args.currency.toUpperCase(),
            value: toPayPalAmount(args.amount, args.currency),
          },
        },
      ],
    }),
  });
  if (!res.ok) throw new Error(`PayPal create order failed (${res.status})`);
  const json = (await res.json()) as PayPalOrderResult;
  if (!json.id) throw new Error("PayPal create order: no id");
  return json;
}

export type PayPalCapture = {
  status: string; // COMPLETED when paid
  currency: string;
  amount: number;
  captureId: string | null;
  raw: unknown;
};

/** Capture a previously created order and normalise the money we actually got. */
export async function capturePayPalOrder(cfg: Creds, orderId: string): Promise<PayPalCapture> {
  const base = paypalApiBase(cfg.mode);
  const token = await accessToken(cfg);
  const res = await fetch(`${base}/v2/checkout/orders/${encodeURIComponent(orderId)}/capture`, {
    method: "POST",
    headers: { Authorization: `Bearer ${token}`, "Content-Type": "application/json" },
    cache: "no-store",
  });
  const json = (await res.json().catch(() => ({}))) as Record<string, unknown>;
  if (!res.ok) {
    // A duplicate capture (order already captured) is not fatal — the reconcile
    // path below re-reads the order. Anything else is a hard failure.
    throw new Error(`PayPal capture failed (${res.status})`);
  }
  return normaliseCapture(json);
}

/** Read an order back (used to reconcile a webhook without re-capturing). */
export async function getPayPalOrder(cfg: Creds, orderId: string): Promise<PayPalCapture> {
  const base = paypalApiBase(cfg.mode);
  const token = await accessToken(cfg);
  const res = await fetch(`${base}/v2/checkout/orders/${encodeURIComponent(orderId)}`, {
    headers: { Authorization: `Bearer ${token}` },
    cache: "no-store",
  });
  const json = (await res.json().catch(() => ({}))) as Record<string, unknown>;
  if (!res.ok) throw new Error(`PayPal get order failed (${res.status})`);
  return normaliseCapture(json);
}

function normaliseCapture(json: Record<string, unknown>): PayPalCapture {
  const units = (json.purchase_units as Array<Record<string, unknown>> | undefined) ?? [];
  const cap = (units[0]?.payments as Record<string, unknown> | undefined)?.captures as
    | Array<Record<string, unknown>>
    | undefined;
  const first = cap?.[0];
  const money = (first?.amount ?? (units[0]?.amount as Record<string, unknown> | undefined)) as
    | { currency_code?: string; value?: string }
    | undefined;
  return {
    status: String((first?.status as string) ?? (json.status as string) ?? ""),
    currency: String(money?.currency_code ?? ""),
    amount: Number(money?.value ?? 0) || 0,
    captureId: (first?.id as string) ?? null,
    raw: json,
  };
}

// Validate a pasted clientId/secret by fetching a token; returns a label.
export async function verifyPayPalCreds(
  clientId: string,
  secret: string,
  mode: PayPalMode
): Promise<{ ok: true; label: string } | { ok: false }> {
  try {
    await accessToken({ clientId, secret, mode });
    return { ok: true, label: `${mode === "live" ? "Live" : "Sandbox"} app connected` };
  } catch {
    return { ok: false };
  }
}

/** Verify a webhook's signature with PayPal (requires the studio's webhookId). */
export async function verifyPayPalWebhook(
  cfg: Creds & { webhookId?: string },
  headers: Headers,
  rawBody: string
): Promise<boolean> {
  if (!cfg.webhookId) return false;
  try {
    const base = paypalApiBase(cfg.mode);
    const token = await accessToken(cfg);
    const res = await fetch(`${base}/v1/notifications/verify-webhook-signature`, {
      method: "POST",
      headers: { Authorization: `Bearer ${token}`, "Content-Type": "application/json" },
      cache: "no-store",
      body: JSON.stringify({
        auth_algo: headers.get("paypal-auth-algo"),
        cert_url: headers.get("paypal-cert-url"),
        transmission_id: headers.get("paypal-transmission-id"),
        transmission_sig: headers.get("paypal-transmission-sig"),
        transmission_time: headers.get("paypal-transmission-time"),
        webhook_id: cfg.webhookId,
        webhook_event: JSON.parse(rawBody),
      }),
    });
    if (!res.ok) return false;
    const json = (await res.json()) as { verification_status?: string };
    return json.verification_status === "SUCCESS";
  } catch {
    return false;
  }
}

import { db } from "@/lib/db";
import { emitEvent } from "@/lib/webhooks";
import { initialExpiry } from "@/lib/memberships";
import { moneyFormatter } from "@/lib/tenant";
import { sendEmail } from "@/lib/mailer";
import { allocateUniqueCode, purchaseEmailBody, GIFT_CARD_VALIDITY_DAYS } from "@/lib/gift-cards";
import type { PayPalCapture } from "@/lib/paypal";

// Turn a *captured* PayPal order into the exact same records a paid Stripe
// checkout would produce — a package Order + ClientPackage, or a minted
// GiftCard — so everything downstream (POS, my-packages, gift-card redemption)
// works identically no matter which processor was used.
//
// The grant is driven entirely by the server-side PayPalOrder intent row written
// at create-order time — never by client input — and is idempotent: the unique
// Order.paypalOrderId / GiftCard.paypalOrderId columns mean a retry, a double
// capture, or a webhook arriving after the browser capture can only ever find
// the existing record instead of granting twice.

export type GrantResult =
  | { ok: true; redirect: string }
  | { ok: false; redirect: string };

const AMOUNT_TOLERANCE = 0.01;

export async function fulfillPayPalOrder(args: {
  orderId: string;
  capture: PayPalCapture;
  slug: string;
  baseUrl: string; // origin, no trailing slash
}): Promise<GrantResult> {
  const { orderId, capture, slug, baseUrl } = args;
  const intent = await db.payPalOrder.findUnique({ where: { paypalId: orderId } });
  if (!intent) return { ok: false, redirect: `/book/${slug}/packages?err=paypal` };

  const backPackages = `/book/${slug}/packages?err=paypal`;
  const backGift = `/book/${slug}/gift-cards?err=stripe`;
  const back = intent.kind === "giftcard" ? backGift : backPackages;

  // The money PayPal actually captured must match what we asked to charge.
  if (
    capture.status !== "COMPLETED" ||
    capture.currency.toUpperCase() !== intent.currency.toUpperCase() ||
    Math.abs(capture.amount - Number(intent.amount)) > AMOUNT_TOLERANCE
  ) {
    return { ok: false, redirect: back };
  }

  const tenant = await db.tenant.findUnique({ where: { id: intent.tenantId } });
  if (!tenant) return { ok: false, redirect: back };

  if (intent.kind === "package") {
    if (!intent.clientId || !intent.packageId) return { ok: false, redirect: back };
    const existing = await db.order.findUnique({ where: { paypalOrderId: orderId } });
    if (!existing) {
      const pkg = await db.package.findFirst({ where: { id: intent.packageId, tenantId: tenant.id } });
      if (!pkg) return { ok: false, redirect: back };
      try {
        await db.$transaction(async (tx) => {
          const last = await tx.order.findFirst({ where: { tenantId: tenant.id }, orderBy: { number: "desc" }, select: { number: true } });
          await tx.order.create({
            data: {
              tenantId: tenant.id, clientId: intent.clientId, number: (last?.number ?? 0) + 1,
              total: pkg.price, method: "paypal", status: "PAID", paypalOrderId: orderId,
              items: { create: [{ kind: "package", refId: pkg.id, label: pkg.name, qty: 1, unitPrice: pkg.price }] },
            },
          });
          await tx.clientPackage.create({
            data: { tenantId: tenant.id, clientId: intent.clientId!, packageId: pkg.id, creditsLeft: pkg.credits, expiresAt: initialExpiry(pkg), pricePaid: pkg.price },
          });
        });
      } catch {
        // Unique paypalOrderId collision → another path already granted; fall through.
      }
    }
    await db.payPalOrder.update({ where: { paypalId: orderId }, data: { status: "CAPTURED", captureId: capture.captureId } }).catch(() => {});
    emitEvent(tenant.id, "order.paid", { total: "", currency: tenant.currency, label: "package (paid online — PayPal)" });
    return { ok: true, redirect: `/book/${slug}/my-packages?ok=paid` };
  }

  // Gift card
  let card = await db.giftCard.findUnique({ where: { paypalOrderId: orderId } });
  if (!card) {
    const amount = Number(intent.amount);
    const code = await allocateUniqueCode(db, tenant.id);
    const expiresAt = new Date(Date.now() + GIFT_CARD_VALIDITY_DAYS * 86400_000);
    try {
      card = await db.$transaction(async (tx) => {
        const created = await tx.giftCard.create({
          data: {
            tenantId: tenant.id, code,
            initialAmount: amount.toFixed(2), balance: amount.toFixed(2), currency: tenant.currency,
            purchaserEmail: intent.purchaserEmail, recipientEmail: intent.recipientEmail, message: intent.message,
            status: "ACTIVE", expiresAt, paypalOrderId: orderId,
          },
        });
        await tx.giftCardTxn.create({ data: { giftCardId: created.id, amount: amount.toFixed(2), type: "PURCHASE", note: "Online purchase (PayPal)" } });
        return created;
      });
    } catch {
      card = await db.giftCard.findUnique({ where: { paypalOrderId: orderId } });
    }

    const to = card?.recipientEmail || card?.purchaserEmail;
    if (card && to) {
      const fmt = moneyFormatter(tenant.currency);
      const viewUrl = `${baseUrl}/book/${slug}/gift-cards/${encodeURIComponent(card.code)}`;
      const { subject, body } = purchaseEmailBody({
        studio: tenant.name, amount: fmt.format(Number(card.initialAmount)), code: card.code, message: card.message, viewUrl,
      });
      await sendEmail({ tenantId: tenant.id, to, subject, body }).catch(() => {});
    }
  }
  await db.payPalOrder.update({ where: { paypalId: orderId }, data: { status: "CAPTURED", captureId: capture.captureId } }).catch(() => {});
  if (!card) return { ok: false, redirect: backGift };
  emitEvent(tenant.id, "order.paid", { total: "", currency: tenant.currency, label: "gift card (paid online — PayPal)" });
  return { ok: true, redirect: `/book/${slug}/gift-cards/${encodeURIComponent(card.code)}?ok=purchased` };
}

import { NextResponse } from "next/server";
import { rateLimit } from "@/lib/rate-limit";
import { db } from "@/lib/db";
import { tenantBySlugOrDomain } from "@/lib/public-tenant";
import { getCustomerSession } from "@/lib/customer-auth";
import { studioPayPalConfig, studioPayPalEnabled, createPayPalOrder } from "@/lib/paypal";
import { GIFT_CARD_MIN, GIFT_CARD_MAX } from "@/lib/gift-cards";

// Create a PayPal Orders-v2 order for a package or gift-card purchase, using the
// STUDIO's own PayPal app. The amount is always computed server-side (package
// price from the DB; gift-card amount validated against the studio's limits) —
// the client never dictates what it will be charged. The order + a server-side
// intent row are written; the browser SDK then approves and we capture in
// /api/public/paypal/capture. If PayPal isn't enabled this cleanly 400s and no
// button ever reaches this route.
export async function POST(req: Request) {
  if (!rateLimit(req, "pp-create", 12, 60)) return NextResponse.json({ error: "slow_down" }, { status: 429 });

  let body: Record<string, unknown> = {};
  try { body = await req.json(); } catch { return NextResponse.json({ error: "bad_request" }, { status: 400 }); }

  const slug = String(body.slug ?? "");
  const kind = String(body.kind ?? "");
  const tenant = await tenantBySlugOrDomain(slug);
  if (!tenant || tenant.status === "SUSPENDED") return NextResponse.json({ error: "unavailable" }, { status: 400 });
  const cfg = studioPayPalConfig(tenant);
  if (!studioPayPalEnabled(tenant)) return NextResponse.json({ error: "paypal_off" }, { status: 400 });

  try {
    if (kind === "package") {
      const packageId = String(body.packageId ?? "");
      const customer = await getCustomerSession();
      if (!customer || customer.tenantId !== tenant.id) return NextResponse.json({ error: "auth" }, { status: 401 });
      const pkg = await db.package.findFirst({ where: { id: packageId, tenantId: tenant.id, active: true } });
      const client = await db.client.findFirst({ where: { id: customer.clientId, tenantId: tenant.id } });
      if (!pkg || !client) return NextResponse.json({ error: "not_found" }, { status: 404 });

      const amount = Number(pkg.price);
      const order = await createPayPalOrder(cfg, {
        currency: tenant.currency,
        amount,
        description: `${pkg.name} — ${tenant.name}`,
        referenceId: "package",
      });
      await db.payPalOrder.create({
        data: {
          paypalId: order.id, tenantId: tenant.id, kind: "package",
          clientId: client.id, packageId: pkg.id,
          amount: amount.toFixed(2), currency: tenant.currency, status: "CREATED",
        },
      });
      return NextResponse.json({ id: order.id });
    }

    if (kind === "giftcard") {
      const custom = Number(body.amountCustom ?? 0) || 0;
      const preset = Number(body.amount ?? 0) || 0;
      const amount = Math.round((custom > 0 ? custom : preset) * 100) / 100;
      const recipientEmail = String(body.recipientEmail ?? "").trim().slice(0, 200);
      const purchaserEmail = String(body.purchaserEmail ?? "").trim().slice(0, 200);
      const message = String(body.message ?? "").trim().slice(0, 500);
      if (amount < GIFT_CARD_MIN || amount > GIFT_CARD_MAX) return NextResponse.json({ error: "amount" }, { status: 400 });
      if (!/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(recipientEmail)) return NextResponse.json({ error: "email" }, { status: 400 });

      const order = await createPayPalOrder(cfg, {
        currency: tenant.currency,
        amount,
        description: `Gift card — ${tenant.name}`,
        referenceId: "giftcard",
      });
      await db.payPalOrder.create({
        data: {
          paypalId: order.id, tenantId: tenant.id, kind: "giftcard",
          amount: amount.toFixed(2), currency: tenant.currency, status: "CREATED",
          recipientEmail: recipientEmail || null, purchaserEmail: purchaserEmail || null, message: message || null,
        },
      });
      return NextResponse.json({ id: order.id });
    }

    return NextResponse.json({ error: "bad_kind" }, { status: 400 });
  } catch {
    return NextResponse.json({ error: "paypal" }, { status: 502 });
  }
}

import { NextResponse } from "next/server";
import { rateLimit } from "@/lib/rate-limit";
import { tenantBySlugOrDomain } from "@/lib/public-tenant";
import { studioPayPalConfig, studioPayPalEnabled, capturePayPalOrder, getPayPalOrder } from "@/lib/paypal";
import { fulfillPayPalOrder } from "@/lib/paypal-grant";
import { externalUrl } from "@/lib/request-url";

// Approve → capture. The browser tells us WHICH order to capture; we then call
// PayPal ourselves, confirm the capture COMPLETED and that the money matches the
// server-side intent, and only then grant the purchase. The client is never
// trusted for the amount or for the fact of payment — everything is re-verified
// against PayPal here before any package/gift-card is created.
export async function POST(req: Request) {
  if (!rateLimit(req, "pp-capture", 12, 60)) return NextResponse.json({ error: "slow_down" }, { status: 429 });

  let body: Record<string, unknown> = {};
  try { body = await req.json(); } catch { return NextResponse.json({ error: "bad_request" }, { status: 400 }); }
  const slug = String(body.slug ?? "");
  const orderId = String(body.orderID ?? body.orderId ?? "");
  if (!orderId) return NextResponse.json({ error: "bad_request" }, { status: 400 });

  const tenant = await tenantBySlugOrDomain(slug);
  if (!tenant) return NextResponse.json({ error: "unavailable" }, { status: 400 });
  const cfg = studioPayPalConfig(tenant);
  if (!studioPayPalEnabled(tenant)) return NextResponse.json({ error: "paypal_off" }, { status: 400 });

  const origin = externalUrl(req, "").toString().replace(/\/$/, "");
  try {
    let capture;
    try {
      capture = await capturePayPalOrder(cfg, orderId);
    } catch {
      // Already captured (e.g. a retried approve) — read the order back instead.
      capture = await getPayPalOrder(cfg, orderId);
    }
    const result = await fulfillPayPalOrder({ orderId, capture, slug, baseUrl: origin });
    return NextResponse.json(result, { status: result.ok ? 200 : 402 });
  } catch {
    return NextResponse.json({ ok: false, redirect: `/book/${slug}/packages?err=paypal` }, { status: 502 });
  }
}

import { NextResponse } from "next/server";
import { db } from "@/lib/db";
import { studioPayPalConfig, getPayPalOrder, verifyPayPalWebhook } from "@/lib/paypal";
import { fulfillPayPalOrder } from "@/lib/paypal-grant";
import { externalUrl } from "@/lib/request-url";

// PayPal webhook reconciler. The browser capture is the primary grant path; this
// endpoint is the safety net for the case where the customer closes the tab
// after paying. It resolves the tenant from our own intent row, verifies the
// webhook SIGNATURE against that studio's PayPal app (requires the studio to
// have saved its webhook id), then re-runs the SAME idempotent grant — so a
// webhook arriving after a successful browser capture is a harmless no-op.
//
// Register this URL in the studio's PayPal app:  /api/public/paypal/webhook
export async function POST(req: Request) {
  const raw = await req.text();
  let event: Record<string, unknown> = {};
  try { event = JSON.parse(raw); } catch { return NextResponse.json({ ok: true }); }

  const orderId = extractOrderId(event);
  if (!orderId) return NextResponse.json({ ok: true }); // nothing we track — ack

  const intent = await db.payPalOrder.findUnique({ where: { paypalId: orderId } });
  if (!intent) return NextResponse.json({ ok: true }); // not ours — ack

  const tenant = await db.tenant.findUnique({ where: { id: intent.tenantId } });
  if (!tenant) return NextResponse.json({ ok: true });
  const cfg = studioPayPalConfig(tenant);

  // Verify the signature. Without a configured webhookId we cannot trust the
  // event, so we ack (200, no retries) but do NOT grant — the browser capture
  // path remains authoritative.
  const verified = await verifyPayPalWebhook(cfg, req.headers, raw);
  if (!verified) return NextResponse.json({ ok: true });

  const type = String(event.event_type ?? "");
  if (type === "PAYMENT.CAPTURE.COMPLETED" || type === "CHECKOUT.ORDER.COMPLETED" || type === "CHECKOUT.ORDER.APPROVED") {
    try {
      const capture = await getPayPalOrder(cfg, orderId);
      const origin = externalUrl(req, "").toString().replace(/\/$/, "");
      await fulfillPayPalOrder({ orderId, capture, slug: intent.tenantId, baseUrl: origin });
    } catch {
      // Reconcile best-effort; PayPal will retry on a non-2xx, but we still ack.
    }
  }
  return NextResponse.json({ ok: true });
}

function extractOrderId(event: Record<string, unknown>): string | null {
  const resource = event.resource as Record<string, unknown> | undefined;
  if (!resource) return null;
  const related = ((resource.supplementary_data as Record<string, unknown> | undefined)?.related_ids ??
    {}) as Record<string, unknown>;
  return (
    (related.order_id as string | undefined) ??
    (resource.id as string | undefined) ??
    null
  );
}

