const fs = require("node:fs");
for (const line of fs.readFileSync("/opt/nxeon/.env", "utf8").split("\n")) {
  const m = line.match(/^\s*([A-Z0-9_]+)\s*=\s*(.*)\s*$/);
  if (m && process.env[m[1]] === undefined) {
    let v = m[2];
    if ((v.startsWith('"') && v.endsWith('"')) || (v.startsWith("'") && v.endsWith("'"))) v = v.slice(1, -1);
    process.env[m[1]] = v;
  }
}
const { PrismaClient } = require("/opt/nxeon/node_modules/@prisma/client");
const db = new PrismaClient();
const CARD = "cmsbkfrlq001phlv5699zqzcp";
const COL = "cmsbk8miq0017hlv5elhzx9vf";
const BODY = process.argv[2];
(async () => {
  const card = await db.card.findUnique({ where: { id: CARD }, include: { attachments: true, column: true } });
  if (!card) { console.log("CARD NOT FOUND"); process.exit(1); }
  const col = await db.boardColumn.findUnique({ where: { id: COL } });
  console.log("CARD:", card.title, "| current column:", card.column?.name, "| target:", col?.name);
  console.log("attachments:", card.attachments.map(a => a.filename).join(", ") || "(none)");
  await db.card.update({ where: { id: CARD }, data: { columnId: COL } });
  await db.cardComment.create({ data: { cardId: CARD, authorName: "Claude", body: BODY } });
  console.log("MOVED + COMMENTED");
  await db.$disconnect();
})().catch(e => { console.error(e.message); process.exit(1); });
